#
# Export-all version script: enabling version_script must not change the ABI,
# so every symbol stays global here (the linked output is identical to the one
# built without a version script). Narrowing to an explicit whitelist together
# with "local: *;" will be done in a follow-up change that also covers every
# consumer of this library.

{
  global:
    *;
};
